using Microsoft.EntityFrameworkCore;using ZosyalMedya.Modules.Administration.Domain.Configuration;using ZosyalMedya.Modules.Administration.Infrastructure.Persistence;using Xunit;
namespace ZosyalMedya.Tests.Integration.Administration;public sealed class AdministrationRepositoryTests{[Fact]public async Task FlagsSettingsAndAtomicMetricsPersist(){if(!InfrastructureTestGate.IsEnabled)return;await using var db=new AdministrationDbContext(new DbContextOptionsBuilder<AdministrationDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();var repository=new PostgreSqlAdministrationRepository(db);var suffix=Guid.NewGuid().ToString("N");var metricName=$"metric.{suffix}";var flag=FeatureFlag.Create(FeatureFlagId.New(),$"test.{suffix}","Sözleşme",true,25,DateTimeOffset.UtcNow);await repository.SaveFlagAsync(flag,null,default);var setting=SystemSetting.Create($"ui.{suffix}","{\"theme\":\"system\"}","Arayüz",DateTimeOffset.UtcNow);await repository.SaveSettingAsync(setting,null,default);await repository.IncrementMetricAsync(metricName,2,DateTimeOffset.UtcNow,default);await repository.IncrementMetricAsync(metricName,3,DateTimeOffset.UtcNow,default);Assert.Equal(5,(await repository.ListMetricsAsync(default)).Single(x=>x.Name==metricName).Value);await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM administration.feature_flags WHERE \"Id\" = {flag.Id.Value}");await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM administration.settings WHERE \"Id\" = {setting.Id}");await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM administration.metrics WHERE \"Name\" = {metricName}");}}
